/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["weiterkommen"]={"Ein berufliches Entwicklungsziel bestimmen":"تعیین یک هدف پیشرفت کاری","Du leitest aus einer gewünschten Tätigkeit einen realistischen nächsten Lernschritt ab.":"شما از یک کار دلخواه یک قدم یادگیری واقع‌بینانهٔ بعدی بیرون می‌کشید.","Kursname als Berufsziel behandeln":"نام کورس را هدف شغلی دانستن","Falsch: „Mein Ziel ist irgendein Zertifikat.“ Richtig: Eine gewünschte Tätigkeit und den dafür passenden Lernbedarf beschreiben.":"اشتباه: «هدف من یک گواهی‌نامهٔ هر چه باشد است.» درست: یک کار دلخواه و نیاز یادگیری مناسب آن را توصیف کنید.","Lernplan als Beförderungszusage lesen":"برنامهٔ یادگیری را وعدهٔ ترفیع خواندن","Falsch: Eine geplante Weiterbildung als sichere neue Stelle darstellen. Richtig: Lernen und betriebliche Entscheidung unterscheiden.":"اشتباه: یک آموزش برنامه‌ریزی‌شده را کار تازهٔ مطمئن نشان دهید. درست: یادگیری و تصمیم شرکت را جدا کنید.","Welche Tätigkeit möchte Seda unterstützen?":"سدا در کدام کار می‌خواهد کمک کند؟","Die vollständige Personalabrechnung.":"صورت‌حساب کامل کارکنان.","Die Bestandsplanung.":"برنامه‌ریزی موجودی.","Die selbstständige Leitung der gesamten Abteilung.":"رهبری مستقل تمام بخش.","Seda nennt die Bestandsplanung ausdrücklich als gewünschte nächste Aufgabe.":"سدا صریحاً برنامه‌ریزی موجودی را کار دلخواه بعدی می‌نامد.","Was ist ein überprüfbares Lernergebnis?":"یک نتیجهٔ یادگیری قابل بررسی چیست؟","Eine Teilnahme an irgendeinem Kurs ohne Anwendung.":"شرکت در هر کورسی بدون به کار بردن.","Ein allgemeiner Vorsatz, bald sicherer zu werden.":"یک تصمیم کلی برای زودتر مطمئن‌تر شدن.","Eine verständliche Tabellenauswertung mit Beispieldaten.":"یک ارزیابی قابل فهم جدول با داده‌های نمونه.","Eine konkrete Auswertung lässt sich anhand von Kriterien besprechen.":"یک ارزیابی مشخص را می‌توان بر اساس معیارها صحبت کرد.","Was muss vor der Kurswahl geklärt werden?":"پیش از انتخاب کورس چه چیزی باید روشن شود؟","Die tatsächlichen Anforderungen der Zielaufgabe.":"خواسته‌های واقعی کار هدف.","Nur ob der Kurstitel nach einer höheren Position klingt.":"فقط اینکه آیا عنوان کورس شبیه یک مقام بالاتر است.","Nur ob eine Kollegin denselben Kurs schon besucht hat.":"فقط اینکه آیا یک همکار همان کورس را رفته است.","Nur bekannte Anforderungen ermöglichen die Prüfung, ob ein Kurs zum Ziel passt.":"فقط خواسته‌های دانسته‌شده بررسی جور بودن یک کورس با هدف را ممکن می‌کنند.","Formuliere das Ziel als Tätigkeit, die du künftig ausführen möchtest, und nicht nur als allgemeinen Wunsch.":"هدف را به شکل کاری بنویسید که در آینده می‌خواهید انجام دهید، نه فقط یک آرزوی کلی.","Vom Wunsch zur konkreten Tätigkeit kommen":"از آرزو به کار مشخص رسیدن","Seda: „Ich möchte beruflich weiterkommen.“ Berater: „Welche Aufgabe möchtest du übernehmen?“ Seda: „Ich möchte die Bestandsplanung unterstützen.“ Berater: „Was kannst du schon?“ Seda: „Bestände erfassen. Beim Auswerten von Tabellen brauche ich noch Übung.“ Berater: „Dann prüfen wir genau diesen Lernbedarf.“":"سدا: «می‌خواهم در کارم پیشرفت کنم.» مشاور: «کدام کار را می‌خواهی به عهده بگیری؟» سدا: «می‌خواهم در برنامه‌ریزی موجودی کمک کنم.» مشاور: «از قبل چه بلدی؟» سدا: «ثبت موجودی. در ارزیابی جدول‌ها هنوز تمرین لازم دارم.» مشاور: «پس دقیقاً همین نیاز یادگیری را بررسی می‌کنیم.»","Ziel und Mittel unterscheiden":"جدا کردن هدف و وسیله","Ein Kurs ist ein mögliches Mittel, nicht automatisch das berufliche Ziel. „Tabellen auswerten, um die Bestandsplanung zu unterstützen“ beschreibt den Zusammenhang. Sammle vorhandene Fähigkeiten und die noch fehlende konkrete Handlung. Frage im Betrieb nach den tatsächlichen Anforderungen, bevor du aus einem interessanten Kurstitel eine nötige Qualifikation ableitest.":"یک کورس یک وسیلهٔ ممکن است، نه خودکار هدف شغلی. „Tabellen auswerten, um die Bestandsplanung zu unterstützen“ (ارزیابی جدول‌ها برای کمک به برنامه‌ریزی موجودی) پیوند را توصیف می‌کند. توانایی‌های موجود و کار مشخص هنوز کم را جمع کنید. در شرکت دربارهٔ خواسته‌های واقعی بپرسید، پیش از اینکه از یک عنوان جالب کورس یک صلاحیت لازم نتیجه بگیرید.","Ein überprüfbares Ergebnis wählen":"انتخاب یک نتیجهٔ قابل بررسی","Lege fest, woran du deinen Fortschritt erkennst. Für Seda kann das eine Auswertung mit Beispieldaten sein. Besprecht vorher, was sie zeigen soll: etwa Bestände und fehlende Mengen. Bitte danach um Rückmeldung zu genau diesen Punkten. „Besser werden“ ist als Ziel zu ungenau. Ein sichtbares Ergebnis lässt sich gemeinsam prüfen.":"تعیین کنید پیشرفت خود را از کجا می‌شناسید. برای سدا این می‌تواند یک ارزیابی با داده‌های نمونه باشد. پیش از آن صحبت کنید که باید چه چیزی را نشان دهد: مثلاً موجودی و مقدارهای کم. بعد دربارهٔ دقیقاً همین نکته‌ها بازخورد بخواهید. «بهتر شدن» برای هدف خیلی نامشخص است. یک نتیجهٔ قابل دید را می‌توان با هم بررسی کرد.","Den nächsten Schritt begrenzen":"محدود کردن قدم بعدی","Plane zunächst eine kleine Erkundung: Anforderungen erfragen, Kursinhalte vergleichen oder eine Übungsaufgabe durchführen. Eine neue Tätigkeit ist erst dann fest zugesagt, wenn die zuständige Stelle das tatsächlich bestätigt. Der Lernplan darf sich nach einer Rückmeldung ändern. Ein realistischer Zwischenschritt ist wertvoller als eine sichere Beförderung zu behaupten.":"اول یک بررسی کوچک برنامه‌ریزی کنید: خواسته‌ها را بپرسید، محتوای کورس‌ها را مقایسه کنید یا یک کار تمرینی انجام دهید. یک کار تازه فقط وقتی قطعی وعده داده شده که بخش مسئول آن را واقعاً تأیید کند. برنامهٔ یادگیری می‌تواند بعد از یک بازخورد تغییر کند. یک قدم میانی واقع‌بینانه ارزشمندتر از ادعای یک ترفیع مطمئن است.","Den Bedarf ergänzen":"کامل کردن نیاز","Setze „Bestandsplanung“ und „Tabellen“ ein.":"„Bestandsplanung“ (برنامه‌ریزی موجودی) و „Tabellen“ (جدول‌ها) را بگذارید.","Verbinde Zielaufgabe und fehlende Handlung.":"کار هدف و کار کم را وصل کنید.","Die beiden Angaben begründen einen gezielten Lernschritt.":"این دو معلومات یک قدم یادگیری هدفمند را توجیه می‌کنند.","Seda möchte die ___ unterstützen.":"Seda möchte die ___ unterstützen. (سدا می‌خواهد در ___ کمک کند.)","Sie braucht Übung beim Auswerten von ___.":"Sie braucht Übung beim Auswerten von ___. (او در ارزیابی ___ تمرین لازم دارد.)","Planungsbegriffe zuordnen":"وصل کردن مفهوم‌های برنامه‌ریزی","Verbinde Beispiel und Funktion.":"مثال و کارکرد را وصل کنید.","Das Mittel soll zur gewünschten Tätigkeit führen.":"وسیله باید به کار دلخواه برسد.","Ziel, Handlung und Prüfung gehören zusammen.":"هدف، کار و بررسی با هم هستند.","Bestandsplanung unterstützen":"کمک در برنامه‌ریزی موجودی","Tabellen auswerten üben":"تمرین ارزیابی جدول‌ها","Auswertung besprechen":"صحبت دربارهٔ ارزیابی","Die vorhandene Fähigkeit hören":"شنیدن توانایی موجود","Was kann Seda bereits erfassen?":"سدا از قبل چه چیزی را می‌تواند ثبت کند؟","Gesucht ist das Vorwissen, nicht die Lernlücke.":"دانش قبلی پرسیده شده، نه کمبود یادگیری.","Seda beherrscht bereits die Bestandserfassung.":"سدا از قبل ثبت موجودی (Bestände) را بلد است.","Ein Entwicklungsziel schreiben":"نوشتن یک هدف پیشرفت","Schreibe vier Sätze mit Ziel, Vorwissen, Lernbedarf und erstem Prüfschritt.":"چهار جمله با هدف، دانش قبلی، نیاز یادگیری و اولین قدم بررسی بنویسید.","Eine überprüfbare Handlung ist hilfreicher als eine allgemeine Eigenschaft.":"یک کار قابل بررسی مفیدتر از یک ویژگی کلی است.","Der Plan verbindet berufliche Richtung und machbaren Lernstart.":"این برنامه جهت شغلی و یک شروع یادگیری شدنی را وصل می‌کند.","Ist das Ziel als Tätigkeit formuliert?":"آیا هدف به شکل کار نوشته شده است؟","Nennst du vorhandenes Können?":"آیا توانایی موجود را نام می‌برید؟","Ist der Lernbedarf konkret begrenzt?":"آیا نیاز یادگیری مشخص محدود است؟","Enthält der erste Schritt eine passende Rückmeldung?":"آیا قدم اول یک بازخورد مناسب دارد؟","Das Entwicklungsziel beschreibt eine gewünschte Tätigkeit.":"هدف پیشرفت یک کار دلخواه را توصیف می‌کند.","Ein Lernschritt wird an einem konkreten Ergebnis überprüft.":"یک قدم یادگیری بر اساس یک نتیجهٔ مشخص بررسی می‌شود.","mein NOW: Weiterbildung und Beratung":"mein NOW: آموزش بیشتر و مشوره","Berufliche Anerkennung und Zuständigkeit klären":"روشن کردن به رسمیت شناختن مسلکی و مسئولیت","Du unterscheidest Anerkennung eines Abschlusses und die Entscheidung eines einzelnen Arbeitgebers.":"شما به رسمیت شناختن یک مدرک و تصمیم یک کارفرمای جداگانه را از هم جدا می‌کنید.","Arbeitgeberlob als formale Anerkennung behandeln":"تعریف کارفرما را به رسمیت شناختن رسمی دانستن","Falsch: „Der Betrieb findet meinen Abschluss gut, also ist er amtlich anerkannt.“ Richtig: Eignungseinschätzung und formales Verfahren unterscheiden.":"اشتباه: «شرکت مدرک مرا خوب می‌داند، پس رسماً به رسمیت شناخته شده است.» درست: ارزیابی مناسب بودن و روند رسمی را جدا کنید.","Übersetzung als Bescheid ausgeben":"ترجمه را تصمیم رسمی جلوه دادن","Falsch: Eine übersetzte Urkunde als Anerkennungsentscheidung bezeichnen. Richtig: Dokumentübersetzung und Entscheidung der zuständigen Stelle trennen.":"اشتباه: یک سند ترجمه‌شده را تصمیم به رسمیت شناختن بنامید. درست: ترجمهٔ سند و تصمیم بخش مسئول را جدا کنید.","Was hilft bei der Suche nach der zuständigen Stelle?":"در پیدا کردن بخش مسئول چه چیزی کمک می‌کند؟","Nur das Land des Abschlusses ohne konkrete Berufsbezeichnung.":"فقط کشور مدرک بدون نام مشخص مسلک.","Nur der Name eines interessierten Arbeitgebers.":"فقط نام یک کارفرمای علاقه‌مند.","Berufsbezeichnung und geplanter Arbeitsort.":"نام مسلک و جای کار برنامه‌ریزی‌شده.","Diese Angaben helfen, den konkreten Beruf und die zuständige Stelle einzugrenzen.":"این معلومات کمک می‌کنند مسلک مشخص و بخش مسئول محدود شوند.","Welche Voraussetzung kann trotz positiver Arbeitgeberreaktion gesondert nötig sein?":"با وجود واکنش مثبت کارفرما کدام شرط ممکن است جداگانه لازم باشد؟","Eine erforderliche formale Anerkennung oder Berufszulassung.":"یک به رسمیت شناختن رسمی یا اجازهٔ مسلکی لازم.","Die im Lob schon enthaltene betriebliche Eignungseinschätzung.":"ارزیابی مناسب بودن شرکت که در تعریف از قبل هست.","Der im Beispiel bereits erfolgte erste Kontakt mit dem Betrieb.":"اولین تماس با شرکت که در مثال از قبل انجام شده.","Eine betriebliche Eignungseinschätzung ist nicht automatisch eine staatliche Entscheidung.":"یک ارزیابی مناسب بودن شرکت خودکار یک تصمیم دولتی نیست.","Welche Aussage ist sachlich?":"کدام گفته واقع‌بینانه است؟","Eine übersetzte Urkunde ersetzt die formale Entscheidung.":"یک سند ترجمه‌شده جای تصمیم رسمی را می‌گیرد.","Schul-, Hochschul- und Berufsabschlüsse können unterschiedliche Verfahren haben.":"مدرک‌های مکتب، دانشگاه و آموزش مسلکی ممکن است روندهای مختلف داشته باشند.","Für Schul- und Berufsabschlüsse gilt zwangsläufig dieselbe zuständige Stelle.":"برای مدرک‌های مکتب و مسلکی ناچار همان بخش مسئول اعتبار دارد.","Art des Abschlusses und Ziel bestimmen den passenden Prüfweg.":"نوع مدرک و هدف راه بررسی مناسب را تعیین می‌کنند.","Suche mit Berufsbezeichnung und geplantem Arbeitsort nach der zuständigen Stelle, statt pauschal dieselbe Behörde anzuschreiben.":"با نام مسلک و جای کار برنامه‌ریزی‌شده دنبال بخش مسئول بگردید، به جای اینکه کلی به همان اداره نامه بنویسید.","Eine Anerkennungsfrage einordnen":"جا دادن یک سوال به رسمیت شناختن","Nasir: „Ich habe meinen Berufsabschluss im Ausland gemacht. Kann jeder Betrieb ihn selbst anerkennen?“ Beraterin: „Ein Betrieb kann Ihre Eignung einschätzen. Die formale Anerkennung und ein möglicher Berufszugang sind andere Fragen.“ Nasir: „Wie finde ich die zuständige Stelle?“ Beraterin: „Wir prüfen Beruf und Arbeitsort im Anerkennungs-Finder.“":"ناصر: «مدرک مسلکی‌ام را در خارج گرفته‌ام. آیا هر شرکت می‌تواند خودش آن را به رسمیت بشناسد؟» مشاور: «یک شرکت می‌تواند مناسب بودن شما را ارزیابی کند. به رسمیت شناختن رسمی و یک دسترسی احتمالی به مسلک سوال‌های دیگری هستند.» ناصر: «بخش مسئول را چطور پیدا کنم؟» مشاور: «مسلک و جای کار را در Anerkennungs-Finder بررسی می‌کنیم.»","Reglementierung als eigene Frage prüfen":"بررسی تنظیم‌شده بودن مسلک به عنوان یک سوال جداگانه","Reglementiert heißt: Für die Berufsausübung ist eine bestimmte staatliche Erlaubnis vorgeschrieben. Dafür brauchst du die passende Anerkennung oder Berufszulassung. Bei nicht reglementierten Berufen ist formale Anerkennung für den Zugang oft freiwillig. Sie kann trotzdem helfen. Prüfe die genaue Berufsbezeichnung und weitere Voraussetzungen. Berufliche Anerkennung und Aufenthaltserlaubnis sind getrennte Fragen.":"Reglementiert (تنظیم‌شده) یعنی: برای کار در این مسلک یک اجازهٔ دولتی مشخص لازم است. برای آن به رسمیت شناختن یا اجازهٔ مسلکی مناسب لازم دارید. در مسلک‌های تنظیم‌نشده به رسمیت شناختن رسمی برای دسترسی اغلب داوطلبانه است. با این حال می‌تواند کمک کند. نام دقیق مسلک و شرط‌های دیگر را بررسی کنید. به رسمیت شناختن مسلکی و اجازهٔ اقامت سوال‌های جداگانه هستند.","Das passende Verfahren finden":"پیدا کردن روند مناسب","Prüfe zuerst die Art deines Abschlusses: Schule, Hochschule oder Berufsausbildung. Dafür können verschiedene Stellen zuständig sein. Der Anerkennungs-Finder hilft dir, den passenden Weg zu suchen. Ein Bescheid ist eine schriftliche Entscheidung der zuständigen Stelle. Eine Übersetzung erklärt nur den Text der Urkunde. Sie ist noch kein Anerkennungsbescheid.":"اول نوع مدرک خود را بررسی کنید: مکتب، دانشگاه یا آموزش مسلکی. برای این‌ها ممکن است بخش‌های مختلف مسئول باشند. Anerkennungs-Finder به شما کمک می‌کند راه مناسب را پیدا کنید. یک Bescheid (تصمیم‌نامه) یک تصمیم نوشتاری بخش مسئول است. یک ترجمه فقط متن سند را توضیح می‌دهد. هنوز تصمیم‌نامهٔ به رسمیت شناختن نیست.","Beratung vor Annahmen nutzen":"استفاده از مشوره پیش از فرض‌ها","Notiere Abschlussland, genaue Bezeichnung und gewünschte Tätigkeit, ohne in einer Übung echte Urkunden hochzuladen. Frage die zuständige Stelle nach Verfahren, Unterlagen und möglichen Kosten. Eine positive Arbeitgeberreaktion ersetzt keinen erforderlichen Berufszugang. Auch Anerkennung und aufenthaltsrechtliche Erlaubnis sind getrennte Fragen, die im konkreten Fall geklärt werden müssen.":"کشور مدرک، نام دقیق و کار دلخواه را یادداشت کنید، بدون اینکه در یک تمرین سند واقعی بارگذاری کنید. از بخش مسئول دربارهٔ روند، اسناد و هزینه‌های احتمالی بپرسید. یک واکنش مثبت کارفرما جای یک دسترسی لازم به مسلک را نمی‌گیرد. به رسمیت شناختن و اجازهٔ اقامتی هم سوال‌های جداگانه‌ای هستند که باید در مورد مشخص روشن شوند.","Anerkennungsbegriffe ergänzen":"کامل کردن مفهوم‌های به رسمیت شناختن","Setze „Beruf“ und „Arbeitsort“ ein.":"„Beruf“ (مسلک) و „Arbeitsort“ (جای کار) را بگذارید.","Eine Zuständigkeit wird nicht allein aus dem Namen einer Person abgeleitet.":"یک مسئولیت فقط از نام یک شخص نتیجه گرفته نمی‌شود.","Beruf und Ort grenzen den Verfahrensweg ein.":"مسلک و جا راه روند را محدود می‌کنند.","Für die Orientierung wird der konkrete ___ geprüft.":"Für die Orientierung wird der konkrete ___ geprüft. (برای راهنمایی ___ مشخص بررسی می‌شود.)","Zusätzlich ist der geplante ___ wichtig.":"Zusätzlich ist der geplante ___ wichtig. (علاوه بر آن ___ برنامه‌ریزی‌شده مهم است.)","Verfahren und Dokumente trennen":"جدا کردن روند و اسناد","Ordne die Begriffe zu.":"مفهوم‌ها را وصل کنید.","Ähnliche Themen erfüllen unterschiedliche Funktionen.":"موضوع‌های مشابه کارکردهای مختلف دارند.","Die Zuordnung verhindert eine Gleichsetzung von Dokument und Entscheidung.":"این وصل کردن از یکی دانستن سند و تصمیم جلوگیری می‌کند.","Übersetzung":"ترجمه","Anerkennungsbescheid":"تصمیم‌نامهٔ به رسمیت شناختن","Arbeitgebergespräch":"گفتگو با کارفرما","Das Suchwerkzeug hören":"شنیدن ابزار جستجو","Welches Werkzeug wird zur Orientierung genannt? Antworte mit dem zusammengesetzten Namen.":"کدام ابزار برای راهنمایی نام برده می‌شود؟ با نام ترکیبی (به آلمانی) جواب دهید.","Gefragt ist das ausdrücklich genannte Suchwerkzeug.":"ابزار جستجوی صریحاً نام‌برده پرسیده شده است.","Der Anerkennungs-Finder hilft, den Verfahrensweg einzugrenzen.":"Anerkennungs-Finder کمک می‌کند راه روند محدود شود.","Eine Anerkennungsfrage vorbereiten":"آماده کردن یک سوال به رسمیت شناختن","Schreibe drei Sätze mit Abschlussart, gewünschter Tätigkeit und Frage nach Zuständigkeit und Unterlagen.":"سه جمله با نوع مدرک، کار دلخواه و سوال دربارهٔ مسئولیت و اسناد بنویسید.","Lasse die zuständige Stelle den konkreten Weg bestätigen.":"بگذارید بخش مسئول راه مشخص را تأیید کند.","Die Anfrage benennt offene Fragen, ohne eine Anerkennung vorwegzunehmen.":"این درخواست سوال‌های باز را نام می‌برد، بدون اینکه به رسمیت شناختن را پیشاپیش فرض کند.","Ist ein Berufsabschluss als Ausgangspunkt genannt?":"آیا یک مدرک مسلکی نقطهٔ شروع نام برده شده است؟","Fragst du nach der konkreten Reglementierung?":"آیا دربارهٔ تنظیم‌شده بودن مشخص مسلک می‌پرسید؟","Beziehst du den geplanten Arbeitsort ein?":"آیا جای کار برنامه‌ریزی‌شده را در نظر می‌گیرید؟","Trennst du Verfahren und Unterlagen von einer schon erfolgten Anerkennung?":"آیا روند و اسناد را از یک به رسمیت شناختن انجام‌شده جدا می‌کنید؟","Stand: November 2026. Allgemeine Information, keine Rechtsberatung. Prüfe aktuelle Regeln bei anerkennung-in-deutschland.de.":"وضعیت: نوامبر 2026. معلومات عمومی، نه مشورهٔ حقوقی. قاعده‌های فعلی را در anerkennung-in-deutschland.de بررسی کنید.","Anerkennung in Deutschland: häufige Fragen":"به رسمیت شناختن در آلمان: سوال‌های رایج","Die zuständige Stelle richtet sich nach dem konkreten Verfahren.":"بخش مسئول بر اساس روند مشخص تعیین می‌شود.","Eine Übersetzung ist nicht dasselbe wie ein Anerkennungsbescheid.":"یک ترجمه همان تصمیم‌نامهٔ به رسمیت شناختن نیست.","Anerkennung: häufige Fragen":"به رسمیت شناختن: سوال‌های رایج","Unterlagen für ein Anerkennungsverfahren ordnen":"مرتب کردن اسناد برای یک روند به رسمیت شناختن","Du leitest eine Unterlagenliste aus dem konkreten Verfahren ab und markierst fehlende Nachweise.":"شما یک لست اسناد را از روند مشخص بیرون می‌کشید و مدرک‌های کم را علامت می‌زنید.","Jede Liste ungeprüft übernehmen":"هر لست را بدون بررسی گرفتن","Falsch: Die Unterlagen eines anderen Berufs als verbindliche eigene Liste verwenden. Richtig: Den Bedarf bei der zuständigen Stelle bestätigen lassen.":"اشتباه: اسناد یک مسلک دیگر را لست قطعی خودتان بدانید. درست: بگذارید بخش مسئول نیاز را تأیید کند.","Scan mit Beglaubigung gleichsetzen":"یکی دانستن اسکن با تصدیق","Falsch: Einen gewöhnlichen Scan als beglaubigte Kopie bezeichnen. Richtig: Formanforderungen ausdrücklich klären.":"اشتباه: یک اسکن معمولی را کاپی تصدیق‌شده بنامید. درست: خواسته‌های شکل را صریحاً روشن کنید.","Was sollte vor umfangreichen Übersetzungsaufträgen geklärt werden?":"پیش از سفارش‌های بزرگ ترجمه چه چیزی باید روشن شود؟","Nur die Dokumentenliste aus dem Verfahren einer Bekannten.":"فقط لست اسناد روند یک آشنا.","Die verlangten Dokumente und Formen.":"اسناد و شکل‌های خواسته‌شده.","Nur die Verfügbarkeit eines Übersetzungsbüros.":"فقط در دسترس بودن یک دفتر ترجمه.","So werden Unterlagen passend zum tatsächlichen Bedarf vorbereitet.":"به این ترتیب اسناد مناسب نیاز واقعی آماده می‌شوند.","Was ist ein Scan nicht automatisch?":"یک اسکن خودکار چه چیزی نیست؟","Eine elektronische Abbildung eines Dokuments.":"یک تصویر الکترونیکی یک سند.","Eine gespeicherte Dokumentdatei.":"یک فایل ذخیره‌شدهٔ سند.","Eine beglaubigte Kopie.":"یک کاپی تصدیق‌شده.","Beglaubigung ist eine eigene Formanforderung und folgt nicht aus Lesbarkeit.":"تصدیق یک خواستهٔ جداگانهٔ شکل است و از خوانایی نتیجه نمی‌شود.","Wie wird ein fehlender Nachweis behandelt?":"با یک مدرک کم چطور رفتار می‌شود؟","Mit der zuständigen Stelle klären.":"با بخش مسئول روشن کردن.","Einen ähnlich klingenden Nachweis ohne Erklärung als Ersatz einreichen.":"یک مدرک شبیه‌نام را بدون توضیح جایگزین فرستادن.","Die Anforderung in der eigenen Übersicht als bereits erfüllt markieren.":"خواسته را در جدول خودتان انجام‌شده علامت زدن.","Die Stelle kann den passenden Umgang im konkreten Verfahren erläutern.":"بخش می‌تواند رفتار مناسب در روند مشخص را توضیح دهد.","Prüfe vor kostenpflichtigen Übersetzungen, welche Form und welche Dokumente die zuständige Stelle tatsächlich verlangt.":"پیش از ترجمه‌های پولی بررسی کنید که بخش مسئول واقعاً کدام شکل و کدام اسناد را می‌خواهد.","Eine Liste gezielt prüfen":"بررسی هدفمند یک لست","Lale: „Ich wollte schon alle Zeugnisse übersetzen lassen.“ Beratungsstelle: „Haben Sie die Liste der zuständigen Stelle?“ Lale: „Noch nicht.“ Beratungsstelle: „Dann klären wir zuerst, welche Unterlagen, Übersetzungen und Formen erforderlich sind.“ Lale: „Ich notiere vorhandene Originale und markiere fehlende Angaben, statt alles sofort zu bestellen.“":"لاله: «می‌خواستم همهٔ تصدیق‌نامه‌ها را ترجمه کنم.» دفتر مشوره: «لست بخش مسئول را دارید؟» لاله: «هنوز نه.» دفتر مشوره: «پس اول روشن می‌کنیم کدام اسناد، ترجمه‌ها و شکل‌ها لازم‌اند.» لاله: «اصل‌های موجود را یادداشت می‌کنم و معلومات کم را علامت می‌زنم، به جای اینکه همه چیز را فوراً سفارش دهم.»","Eine verfahrensbezogene Übersicht anlegen":"ساختن یک جدول مربوط به روند","Lege Spalten für angeforderte Unterlage, vorhanden, benötigte Form und offene Frage an. Eine allgemeine Internetliste muss nicht zu deinem Beruf passen. Richte dich nach der Liste, die deine zuständige Stelle bestätigt hat. Fehlt ein Original oder Nachweis, frage die zuständige Stelle nach dem weiteren Weg. Erfinde keinen Ersatzbeleg.":"ستون‌هایی برای سند خواسته‌شده، موجود، شکل لازم و سوال باز بسازید. یک لست عمومی انترنت لازم نیست با مسلک شما جور باشد. از لستی پیروی کنید که بخش مسئول شما تأیید کرده است. اگر یک اصل یا مدرک کم است، از بخش مسئول دربارهٔ راه بعدی بپرسید. هیچ مدرک جایگزین نسازید.","Original, Kopie und Übersetzung unterscheiden":"جدا کردن اصل، کاپی و ترجمه","Ein Original ist das ursprüngliche Dokument. Eine Kopie gibt es wieder. Eine Übersetzung überträgt den Text in eine andere Sprache. Frage, welche Form benötigt wird. Ein Scan ist nicht automatisch beglaubigt. Eine Beglaubigung bestätigt die Kopie nach dem vorgeschriebenen Verfahren. Versende Originale nur, wenn Bedarf und sicherer Versandweg geklärt sind.":"یک اصل سند اولیه است. یک کاپی آن را تکرار می‌کند. یک ترجمه متن را به زبان دیگر می‌برد. بپرسید کدام شکل لازم است. یک اسکن خودکار تصدیق‌شده نیست. یک تصدیق کاپی را با روند مقرر تأیید می‌کند. اصل‌ها را فقط وقتی بفرستید که نیاز و راه مطمئن فرستادن روشن شده باشد.","Kosten und nächsten Kontakt klären":"روشن کردن هزینه‌ها و تماس بعدی","Frage nach Gebühren, möglicher Beratung und der Reihenfolge der Schritte. Eine angekündigte Unterstützung ist noch keine Kostenübernahme. Halte Antworten mit Datum fest, damit du später weißt, auf welche Liste du dich bezogen hast. In den Kursaufgaben werden nur erfundene Dokumentbezeichnungen verwendet; eine echte Urkunde gehört nicht in ein öffentliches Übungsfeld.":"دربارهٔ فیس‌ها، مشورهٔ احتمالی و ترتیب قدم‌ها بپرسید. یک حمایت اعلام‌شده هنوز پذیرش هزینه نیست. جواب‌ها را با تاریخ ثبت کنید تا بعداً بدانید به کدام لست اشاره کرده‌اید. در کارهای کورس فقط نام‌های ساختگی سند به کار می‌روند؛ یک سند واقعی در یک خانهٔ تمرین عمومی جا ندارد.","Unterlagenstatus ergänzen":"کامل کردن وضعیت اسناد","Setze „vorhanden“ und „offen“ ein.":"„vorhanden“ (موجود) و „offen“ (باز) را بگذارید.","Dokumentbestand und Klärungsbedarf stehen getrennt in der Übersicht.":"موجودی اسناد و نیاز روشن‌سازی در جدول جدا هستند.","Ein vorhandenes Dokument kann weiterhin eine offene Formfrage haben.":"یک سند موجود ممکن است هنوز یک سوال باز شکل داشته باشد.","Das Original liegt bereits vor: ___.":"Das Original liegt bereits vor: ___. (اصل از قبل هست: ___.)","Die benötigte Form ist noch nicht geklärt: ___.":"Die benötigte Form ist noch nicht geklärt: ___. (شکل لازم هنوز روشن نشده: ___.)","Dokumentfassungen zuordnen":"وصل کردن نسخه‌های سند","Verbinde Begriff und Bedeutung.":"مفهوم و معنا را وصل کنید.","Die Fassung sagt noch nicht allein, ob sie für das Verfahren reicht.":"نسخه به تنهایی هنوز نمی‌گوید که آیا برای روند کافی است.","Die Begriffe beschreiben unterschiedliche Dokumentarten.":"این مفهوم‌ها نوع‌های مختلف سند را توصیف می‌کنند.","Original":"اصل","Kopie":"کاپی","Die fehlende Grundlage hören":"شنیدن پایهٔ کم","Welche Liste hat Lale noch nicht? Antworte mit „Unterlagenliste“.":"لاله کدام لست را هنوز ندارد؟ با „Unterlagenliste“ جواب دهید.","Gesucht ist die fehlende verfahrensbezogene Grundlage.":"پایهٔ کم مربوط به روند پرسیده شده است.","Lale braucht zunächst die konkrete Unterlagenliste.":"لاله اول لست مشخص اسناد را لازم دارد.","Eine Unterlagenklärung anfragen":"درخواست روشن‌سازی اسناد","Schreibe drei Sätze: Originale vorhanden, konkrete Liste und Formen erbitten, Übersetzung erst danach planen.":"سه جمله بنویسید: اصل‌ها موجود است، لست و شکل‌های مشخص خواسته می‌شود، ترجمه فقط بعد از آن برنامه‌ریزی می‌شود.","Formuliere eine gezielte Liste offener Fragen statt einen pauschalen Auftrag.":"یک لست هدفمند سوال‌های باز بنویسید، به جای یک سفارش کلی.","Die Anfrage verhindert eine ungeprüfte Gleichsetzung aller Dokumentformen.":"این درخواست از یکی دانستن بررسی‌نشدهٔ همهٔ شکل‌های سند جلوگیری می‌کند.","Ist der vorhandene Bestand klar bezeichnet?":"آیا موجودی فعلی روشن نام برده شده است؟","Fragst du nach dem konkreten Verfahren?":"آیا دربارهٔ روند مشخص می‌پرسید؟","Sind Dokumentbedarf und Formanforderung enthalten?":"آیا نیاز سند و خواستهٔ شکل در آن هست؟","Planst du Übersetzungen erst nach bestätigtem Bedarf?":"آیا ترجمه‌ها را فقط بعد از نیاز تأییدشده برنامه‌ریزی می‌کنید؟","Stand: November 2026. Allgemeine Information, keine Rechtsberatung. Prüfe aktuelle Regeln bei arbeitsagentur.de.":"وضعیت: نوامبر 2026. معلومات عمومی، نه مشورهٔ حقوقی. قاعده‌های فعلی را در arbeitsagentur.de بررسی کنید.","Bundesagentur für Arbeit: Abschluss anerkennen":"ادارهٔ فدرال کار: به رسمیت شناختن مدرک","Unterlagen und Form richten sich nach dem konkreten Verfahren.":"اسناد و شکل بر اساس روند مشخص تعیین می‌شوند.","Eine mögliche Unterstützung ist noch keine bestätigte Kostenübernahme.":"یک حمایت احتمالی هنوز پذیرش تأییدشدهٔ هزینه نیست.","Zuständigkeit und Anerkennungsweg":"مسئولیت و راه به رسمیت شناختن","Weiterbildungen nach Lernziel vergleichen":"مقایسهٔ آموزش‌های بیشتر بر اساس هدف یادگیری","Du prüfst Inhalt, Voraussetzungen, Abschlussform und Vereinbarkeit eines Kurses.":"شما محتوا، پیش‌شرط‌ها، شکل مدرک پایانی و جور بودن یک کورس را بررسی می‌کنید.","Titel als vollständigen Inhalt lesen":"عنوان را محتوای کامل خواندن","Falsch: Aus demselben Titel identische Lerninhalte ableiten. Richtig: Inhalte und tatsächlich geübte Tätigkeiten vergleichen.":"اشتباه: از همان عنوان محتوای یادگیری یکسان نتیجه بگیرید. درست: محتوا و کارهای واقعاً تمرین‌شده را مقایسه کنید.","Online mit zeitlich frei gleichsetzen":"آنلاین را با وقت آزاد یکی دانستن","Falsch: Einen Onlinekurs ohne Prüfung als jederzeit abrufbar einplanen. Richtig: Live-Termine und Eigenlernphasen klären.":"اشتباه: یک کورس آنلاین را بدون بررسی هر وقت قابل دسترس برنامه‌ریزی کنید. درست: وقت‌های زنده و مرحله‌های خودآموزی را روشن کنید.","Welcher Kurs passt eher zu Elias Lernziel?":"کدام کورس بیشتر با هدف یادگیری الیاس جور است؟","A, weil der gemeinsame Titel die Auswertungen bereits einschließt.":"A، چون عنوان مشترک ارزیابی‌ها را از قبل در بر دارد.","B allein wegen des Titels, ohne Voraussetzungen und Zeiten zu prüfen.":"B فقط به خاطر عنوان، بدون بررسی پیش‌شرط‌ها و وقت‌ها.","B, sofern die Voraussetzungen und Zeiten passen.":"B، به شرطی که پیش‌شرط‌ها و وقت‌ها جور باشند.","B nennt die benötigten Auswertungen; die weiteren Bedingungen bleiben zu prüfen.":"B ارزیابی‌های لازم را نام می‌برد؛ شرط‌های دیگر هنوز باید بررسی شوند.","Was ist bei einem Onlinekurs zu klären?":"در یک کورس آنلاین چه چیزی باید روشن شود؟","Ob feste Live-Zeiten vorgesehen sind.":"اینکه آیا وقت‌های ثابت زنده پیش‌بینی شده‌اند.","Ob Online grundsätzlich den Verzicht auf feste Termine bedeutet.":"اینکه آیا آنلاین اصولاً یعنی بدون وقت‌های ثابت.","Ob der Kurstitel schon eine bestandene Prüfung bestätigt.":"اینکه آیا عنوان کورس از قبل یک امتحان قبول‌شده را تأیید می‌کند.","Online sagt allein noch nichts über die zeitliche Organisation.":"آنلاین به تنهایی هنوز چیزی دربارهٔ سازمان‌دهی زمانی نمی‌گوید.","Was belegt ein Suchtreffer auf einem Portal?":"یک نتیجهٔ جستجو در یک پورتال چه چیزی را ثابت می‌کند؟","Dass die persönliche Förderung bereits entschieden ist.":"اینکه حمایت مالی شخصی از قبل تصمیم گرفته شده است.","Dass ein Angebot gefunden wurde, das weiter geprüft werden muss.":"اینکه یک پیشنهاد پیدا شده که باید بیشتر بررسی شود.","Dass die Zugangsvoraussetzungen individuell erfüllt sind.":"اینکه پیش‌شرط‌های ورود به‌طور فردی برآورده شده‌اند.","Treffer, Eignung und Förderung sind unterschiedliche Fragen.":"نتیجهٔ جستجو، مناسب بودن و حمایت مالی سوال‌های مختلف‌اند.","Vergleiche zwei Angebote anhand derselben Lernhandlung, nicht nur anhand ähnlicher Titel.":"دو پیشنهاد را بر اساس همان کار یادگیری مقایسه کنید، نه فقط بر اساس عنوان‌های مشابه.","Zwei Kurse gegeneinander prüfen":"بررسی دو کورس در برابر هم","Elias: „Beide Kurse heißen Tabellen im Beruf.“ Freundin: „Was übt man dort?“ Elias: „A behandelt Dateneingabe, B zusätzlich Auswertungen. Ich brauche die Auswertungen.“ Freundin: „Und die Voraussetzungen?“ Elias: „B verlangt Grundlagen, die ich mit einer Übungsaufgabe prüfen muss.“":"الیاس: «هر دو کورس Tabellen im Beruf (جدول‌ها در کار) نام دارند.» دوستش: «آنجا چه تمرین می‌شود؟» الیاس: «A نوشتن داده را بررسی می‌کند، B علاوه بر آن ارزیابی‌ها را. من ارزیابی‌ها را لازم دارم.» دوستش: «و پیش‌شرط‌ها؟» الیاس: «B پایه‌هایی می‌خواهد که باید با یک کار تمرینی بررسی کنم.»","Inhalt und Titel auseinanderhalten":"جدا نگه داشتن محتوا و عنوان","Ein ähnlicher Kurstitel bedeutet nicht dasselbe Lernziel. Lies die konkreten Inhalte und prüfe, ob du die gewünschte Tätigkeit tatsächlich übst. Frage nach Übungen, Rückmeldung und Abschlussform. Eine Teilnahmebescheinigung ist nicht automatisch eine bestandene Prüfung oder ein anerkannter Berufsabschluss. Die Aussage des Dokuments muss zur Werbung passen.":"یک عنوان مشابه کورس به معنای همان هدف یادگیری نیست. محتوای مشخص را بخوانید و بررسی کنید که آیا کار دلخواه را واقعاً تمرین می‌کنید. دربارهٔ تمرین‌ها، بازخورد و شکل مدرک پایانی بپرسید. یک تصدیق شرکت خودکار یک امتحان قبول‌شده یا یک مدرک مسلکی به رسمیت شناخته‌شده نیست. گفتهٔ سند باید با تبلیغ جور باشد.","Lernform und Alltag abgleichen":"مقایسهٔ شکل یادگیری و زندگی روزمره","Prüfe neben dem Inhalt auch Lernort, Termine und Technik. Ein Onlinekurs kann feste Live-Zeiten haben. Er ist nicht automatisch jederzeit abrufbar. Frage nach der nötigen Vor- und Nachbereitung. Trage diese Zeiten in deinen Wochenplan ein. So erkennst du, ob der Kurs mit Arbeit, Betreuung und Arbeitsweg zusammenpasst.":"علاوه بر محتوا جای یادگیری، وقت‌ها و تکنالوژی را هم بررسی کنید. یک کورس آنلاین ممکن است وقت‌های ثابت زنده داشته باشد. خودکار هر وقت قابل دسترس نیست. دربارهٔ آمادگی و مرور لازم بپرسید. این وقت‌ها را در برنامهٔ هفتهٔ خود بنویسید. به این ترتیب می‌فهمید که آیا کورس با کار، نگهداری از خانواده و راه کار جور است.","Mit einer konkreten Frage weitergehen":"ادامه دادن با یک سوال مشخص","Notiere bei beiden Kursen Inhalte, Voraussetzungen, Abschluss und offene Fragen. Das Portal mein NOW der Bundesagentur für Arbeit bietet Orientierung zu Weiterbildungen und Beratung. Prüfe Inhalt und Qualität jedes gefundenen Angebots. Eine Förderung ist damit noch nicht zugesagt. Bitte den Anbieter um fehlende Angaben und entscheide erst danach, ob das Angebot zu deinem Ziel passt.":"برای هر دو کورس محتوا، پیش‌شرط‌ها، مدرک پایانی و سوال‌های باز را یادداشت کنید. پورتال mein NOW ادارهٔ فدرال کار راهنمایی دربارهٔ آموزش‌های بیشتر و مشوره می‌دهد. محتوا و کیفیت هر پیشنهاد پیداشده را بررسی کنید. با این هنوز حمایت مالی وعده داده نشده است. از ارائه‌دهنده معلومات کم را بخواهید و فقط بعد از آن تصمیم بگیرید که آیا پیشنهاد با هدف شما جور است.","Vergleichskriterien ergänzen":"کامل کردن معیارهای مقایسه","Setze „Inhalte“ und „Voraussetzungen“ ein.":"„Inhalte“ (محتوا) و „Voraussetzungen“ (پیش‌شرط‌ها) را بگذارید.","Unterscheide Lerngegenstand und Zugang.":"موضوع یادگیری و ورود را جدا کنید.","Beide Angaben entscheiden über die Passung des Angebots.":"هر دو معلومات دربارهٔ جور بودن پیشنهاد تصمیم می‌گیرند.","Was wird gelernt? Die ___.":"Was wird gelernt? Die ___. (چه چیزی یاد گرفته می‌شود؟ ___.)","Was muss schon beherrscht werden? Die ___.":"Was muss schon beherrscht werden? Die ___. (چه چیزی را باید از قبل بلد بود؟ ___.)","Kursmerkmale zuordnen":"وصل کردن ویژگی‌های کورس","Verbinde Beispiel und Kategorie.":"مثال و دسته را وصل کنید.","Die Merkmale ergänzen sich im Kursvergleich.":"این ویژگی‌ها در مقایسهٔ کورس همدیگر را کامل می‌کنند.","Ein passender Inhalt allein löst noch nicht alle Planungsfragen.":"یک محتوای مناسب به تنهایی هنوز همهٔ سوال‌های برنامه‌ریزی را حل نمی‌کند.","Auswertungen üben":"تمرین ارزیابی‌ها","Grundlagen nötig":"پایه‌ها لازم است","dienstags live":"سه‌شنبه‌ها زنده","Den Zusatzinhalt hören":"شنیدن محتوای اضافی","Welche zusätzliche Tätigkeit enthält Kurs B?":"کورس B کدام کار اضافی را دارد؟","Gesucht ist der zusätzliche Inhalt.":"محتوای اضافی پرسیده شده است.","Elias braucht gerade die in B genannten Auswertungen.":"الیاس دقیقاً ارزیابی‌های (Auswertungen) نام‌برده در B را لازم دارد.","Eine Kursentscheidung vorbereiten":"آماده کردن یک تصمیم کورس","Schreibe vier Sätze mit Ziel, Inhaltsvergleich, Voraussetzung und offener Zeitfrage.":"چهار جمله با هدف، مقایسهٔ محتوا، پیش‌شرط و سوال باز وقت بنویسید.","Treffe die Entscheidung anhand derselben Kriterien für beide Kurse.":"تصمیم را بر اساس همان معیارها برای هر دو کورس بگیرید.","Der Entwurf verbindet Passung mit noch nötiger Prüfung.":"این پیش‌نویس جور بودن را با بررسی هنوز لازم وصل می‌کند.","Ist das konkrete Lernziel genannt?":"آیا هدف یادگیری مشخص نام برده شده است؟","Vergleichst du tatsächliche Inhalte?":"آیا محتوای واقعی را مقایسه می‌کنید؟","Prüfst du die Voraussetzungen vor Anmeldung?":"آیا پیش‌شرط‌ها را پیش از ثبت‌نام بررسی می‌کنید؟","Beziehst du Termine und zusätzlichen Lernaufwand ein?":"آیا وقت‌ها و زحمت یادگیری اضافی را در نظر می‌گیرید؟","Bundesagentur für Arbeit: Weiterbildung und Beratung":"ادارهٔ فدرال کار: آموزش بیشتر و مشوره","Der konkrete Lerninhalt ist aussagekräftiger als ein allgemeiner Titel.":"محتوای مشخص یادگیری گویاتر از یک عنوان کلی است.","Abschlussart und Teilnahme müssen getrennt gelesen werden.":"نوع مدرک پایانی و شرکت باید جدا خوانده شوند.","mein NOW: Weiterbildungssuche":"mein NOW: جستجوی آموزش بیشتر","Finanzierung und Förderung vor der Anmeldung klären":"روشن کردن تأمین مالی و حمایت پیش از ثبت‌نام","Du unterscheidest Beratung, Antrag und bestätigte Kostenübernahme.":"شما مشوره، درخواست و پذیرش تأییدشدهٔ هزینه را جدا می‌کنید.","Förderfähig als eigene Bewilligung lesen":"قابل حمایت را تأیید شخصی خواندن","Falsch: Aus einer Werbung eine sichere persönliche Kostenübernahme ableiten. Richtig: Individuelle Prüfung und tatsächliche Entscheidung abwarten.":"اشتباه: از یک تبلیغ یک پذیرش مطمئن شخصی هزینه نتیجه بگیرید. درست: منتظر بررسی فردی و تصمیم واقعی بمانید.","Zuschuss mit Gesamtpreis gleichsetzen":"یکی دانستن کمک مالی با قیمت کل","Falsch: Einen möglichen Teilzuschuss als vollständige Finanzierung behandeln. Richtig: Höhe, Umfang und verbleibende Kosten klären.":"اشتباه: یک کمک مالی بخشی احتمالی را تأمین مالی کامل بدانید. درست: اندازه، دامنه و هزینه‌های باقی‌مانده را روشن کنید.","Was bedeutet förderfähig in einer Anzeige nicht automatisch?":"„förderfähig“ (قابل حمایت) در یک اعلان خودکار چه معنایی ندارد؟","Eine persönliche Bewilligung für Meral.":"یک تأیید شخصی برای مرال.","Eine allgemeine Fördermöglichkeit, die individuell geprüft werden muss.":"یک امکان عمومی حمایت که باید فردی بررسی شود.","Einen Hinweis auf ein Förderverfahren mit zu klärenden Voraussetzungen.":"اشاره به یک روند حمایت با پیش‌شرط‌هایی که باید روشن شوند.","Die Werbung ersetzt keine Prüfung ihrer individuellen Voraussetzungen.":"تبلیغ جای بررسی پیش‌شرط‌های فردی او را نمی‌گیرد.","Was muss bei einem Bildungsgutschein geprüft werden?":"در یک Bildungsgutschein (کوپن آموزشی) چه چیزی باید بررسی شود؟","Nur die Werbeaussage des Anbieters ohne persönliche Prüfung.":"فقط گفتهٔ تبلیغاتی ارائه‌دهنده بدون بررسی شخصی.","Nur der Kursname ohne Träger, Bildungsziel und Gültigkeit.":"فقط نام کورس بدون ارائه‌دهنده، هدف آموزشی و اعتبار.","Voraussetzungen, zugelassenes Angebot und konkrete Begrenzungen.":"پیش‌شرط‌ها، پیشنهاد مجاز و محدودیت‌های مشخص.","Die Förderung ist an den persönlichen Fall und die passenden Bedingungen gebunden.":"حمایت به مورد شخصی و شرط‌های مناسب بسته است.","Welche Kostenfrage ist konkret?":"کدام سوال هزینه مشخص است؟","Kann die allgemeine Förderwerbung meine Anmeldung schon verbindlich absichern?":"آیا تبلیغ عمومی حمایت می‌تواند ثبت‌نام مرا از همین حالا قطعی تضمین کند؟","Welche Gebühren und Nebenkosten werden tatsächlich übernommen?":"کدام فیس‌ها و هزینه‌های جانبی واقعاً پذیرفته می‌شوند؟","Reicht der beworbene Zuschuss ohne Klärung verbleibender Kosten?":"آیا کمک مالی تبلیغ‌شده بدون روشن کردن هزینه‌های باقی‌مانده کافی است؟","Die Frage benennt den tatsächlichen Umfang der möglichen Finanzierung.":"این سوال دامنهٔ واقعی تأمین مالی احتمالی را نام می‌برد.","Lasse dir vor einer verbindlichen Buchung erklären, welche Kosten unter welchen Voraussetzungen übernommen werden können.":"پیش از یک رزرو قطعی بخواهید توضیح دهند کدام هزینه‌ها با کدام پیش‌شرط‌ها پذیرفته شوند.","Eine Fördermöglichkeit richtig lesen":"درست خواندن یک امکان حمایت","Meral: „Auf der Webseite steht förderfähig. Kann ich sofort buchen?“ Berater: „Das ist keine persönliche Bewilligung. Erst werden Ihre Voraussetzungen und das konkrete Angebot geprüft.“ Meral: „Dann kläre ich vor dem Vertrag, ob und welche Kosten übernommen werden.“ Berater: „Genau, auch Fristen und Zulassungen können relevant sein.“":"مرال: «در ویب‌سایت نوشته förderfähig. می‌توانم فوراً رزرو کنم؟» مشاور: «این یک تأیید شخصی نیست. اول پیش‌شرط‌های شما و پیشنهاد مشخص بررسی می‌شوند.» مرال: «پس پیش از قرارداد روشن می‌کنم که آیا و کدام هزینه‌ها پذیرفته می‌شوند.» مشاور: «دقیقاً، مهلت‌ها و اجازه‌ها هم ممکن است مهم باشند.»","Förderfähigkeit und Zusage unterscheiden":"جدا کردن قابل حمایت بودن و وعده","Mit einem Bildungsgutschein kann die Agentur für Arbeit eine passende Weiterbildung finanzieren. Im Gespräch prüft sie deine Voraussetzungen. Der Anbieter und die Weiterbildung müssen für die Förderung zugelassen sein. Frage nach den passenden Nachweisen. Ein Gutschein kann nach Ziel, Zeit oder Region begrenzt sein. Eine Werbeaussage bestätigt noch nicht, dass du persönlich die Förderung erhältst.":"با یک Bildungsgutschein (کوپن آموزشی) ادارهٔ کار می‌تواند یک آموزش بیشتر مناسب را تأمین مالی کند. در گفتگو پیش‌شرط‌های شما را بررسی می‌کند. ارائه‌دهنده و آموزش باید برای حمایت مجاز باشند. دربارهٔ مدرک‌های مناسب بپرسید. یک کوپن ممکن است بر اساس هدف، وقت یا منطقه محدود باشد. یک گفتهٔ تبلیغاتی هنوز تأیید نمی‌کند که شما شخصاً حمایت می‌گیرید.","Alle Kostenpositionen erfassen":"ثبت همهٔ بخش‌های هزینه","Eine Bewilligung ist die bestätigte Entscheidung über eine beantragte Förderung. Prüfe, welche Kosten sie tatsächlich abdeckt. Frage nach Kursgebühr, Lernmitteln, Prüfung und nötigen Fahrten. Ein Zuschuss kann nur einen Teil übernehmen. Kläre deshalb, was du selbst bezahlen müsstest. Gehe keine Kostenbindung ein, solange der nötige Ablauf ungeklärt ist.":"یک Bewilligung (تأیید) تصمیم تأییدشده دربارهٔ یک حمایت درخواست‌شده است. بررسی کنید که واقعاً کدام هزینه‌ها را می‌پوشاند. دربارهٔ فیس کورس، وسایل یادگیری، امتحان و رفت‌وآمدهای لازم بپرسید. یک کمک مالی ممکن است فقط بخشی را بپذیرد. پس روشن کنید که خودتان چه چیزی را باید بپردازید. تا وقتی روند لازم روشن نیست، هیچ تعهد هزینه نپذیرید.","Reihenfolge und Belege absichern":"محکم کردن ترتیب و مدرک‌ها","Kläre vor dem Buchen, wann Antrag und Bewilligung nötig sind. Frage, ab wann du dich verbindlich anmelden darfst. Notiere zuständige Stelle, benötigte Unterlagen und Fristen. Bewahre die tatsächliche Entscheidung auf. Notiere, wer welche Kosten übernimmt und was noch offen ist. Prüfe diese Punkte, bevor du einen kostenpflichtigen Vertrag schließt.":"پیش از رزرو روشن کنید که درخواست و تأیید چه وقت لازم‌اند. بپرسید از چه وقت می‌توانید قطعی ثبت‌نام کنید. بخش مسئول، اسناد لازم و مهلت‌ها را یادداشت کنید. تصمیم واقعی را نگه دارید. یادداشت کنید چه کسی کدام هزینه‌ها را می‌پذیرد و چه چیزی هنوز باز است. این نکته‌ها را بررسی کنید، پیش از اینکه یک قرارداد پولی ببندید.","Förderstatus ergänzen":"کامل کردن وضعیت حمایت","Setze „Bewilligung“ und „Kosten“ ein.":"„Bewilligung“ (تأیید) و „Kosten“ (هزینه‌ها) را بگذارید.","Trenne Entscheidung und finanziellen Umfang.":"تصمیم و دامنهٔ مالی را جدا کنید.","Eine Entscheidung muss erklären, was tatsächlich übernommen wird.":"یک تصمیم باید توضیح دهد که واقعاً چه چیزی پذیرفته می‌شود.","Eine persönliche Entscheidung über Förderung: ___.":"Eine persönliche Entscheidung über Förderung: ___. (یک تصمیم شخصی دربارهٔ حمایت: ___.)","Gebühren und nötige Nebenausgaben: ___.":"Gebühren und nötige Nebenausgaben: ___. (فیس‌ها و هزینه‌های جانبی لازم: ___.)","Förderschritte einordnen":"جا دادن قدم‌های حمایت","Verbinde den Stand mit seiner Bedeutung.":"وضعیت را به معنای آن وصل کنید.","Kein früher Schritt ersetzt automatisch den folgenden.":"هیچ قدم زودتر خودکار جای قدم بعدی را نمی‌گیرد.","Die Reihenfolge hält Möglichkeit und tatsächliche Zusage auseinander.":"این ترتیب امکان و وعدهٔ واقعی را جدا نگه می‌دارد.","Beratung":"مشوره","Antrag":"درخواست","Bewilligung":"تأیید","Den nächsten Schritt verstehen":"فهمیدن قدم بعدی","Was will Meral zuerst klären? Antworte mit „Kostenübernahme“.":"مرال اول می‌خواهد چه چیزی را روشن کند؟ با „Kostenübernahme“ جواب دهید.","Gefragt ist die konkrete Finanzierungsfrage.":"سوال مشخص تأمین مالی پرسیده شده است.","Meral will den Umfang der Übernahme vor einer Verpflichtung klären.":"مرال می‌خواهد دامنهٔ پذیرش هزینه را پیش از یک تعهد روشن کند.","Eine Finanzierungsanfrage formulieren":"نوشتن یک درخواست تأمین مالی","Schreibe drei Sätze mit Zielkurs, offener Förderung und Frage nach Reihenfolge und Kostenumfang.":"سه جمله با کورس هدف، حمایت باز و سوال دربارهٔ ترتیب و دامنهٔ هزینه بنویسید.","Eine präzise Anfrage vermeidet eine vorschnelle finanzielle Verpflichtung.":"یک درخواست دقیق از یک تعهد مالی عجولانه جلوگیری می‌کند.","Die Nachricht fragt Bedingungen und Ablauf ab, ohne eine Förderung vorauszusetzen.":"این پیام شرط‌ها و روند را می‌پرسد، بدون اینکه یک حمایت را فرض کند.","Bleibt die Förderung ausdrücklich offen?":"آیا حمایت صریحاً باز می‌ماند؟","Benennst du den konkreten Zielkurs?":"آیا کورس هدف مشخص را نام می‌برید؟","Fragst du nach Voraussetzungen und tatsächlichem Kostenumfang?":"آیا دربارهٔ پیش‌شرط‌ها و دامنهٔ واقعی هزینه می‌پرسید؟","Klärest du die Reihenfolge vor der verbindlichen Anmeldung?":"آیا ترتیب را پیش از ثبت‌نام قطعی روشن می‌کنید؟","Bundesagentur für Arbeit: Bildungsgutschein":"ادارهٔ فدرال کار: کوپن آموزشی (Bildungsgutschein)","Eine Förderwerbung ist keine persönliche Bewilligung.":"یک تبلیغ حمایت یک تأیید شخصی نیست.","Die konkrete Kostenübernahme wird vor einer eigenen Verpflichtung geklärt.":"پذیرش مشخص هزینه پیش از یک تعهد خودتان روشن می‌شود.","Bildungsgutschein: Voraussetzungen und Ablauf":"کوپن آموزشی: پیش‌شرط‌ها و روند","Im Betrieb Entwicklungsmöglichkeiten besprechen":"صحبت دربارهٔ امکان‌های پیشرفت در شرکت","Du fragst nach Anforderungen einer nächsten Aufgabe und vereinbarst einen überprüfbaren Lernversuch.":"شما دربارهٔ خواسته‌های یک کار بعدی می‌پرسید و یک آزمایش یادگیری قابل بررسی توافق می‌کنید.","Übungszusage als Beförderung behandeln":"وعدهٔ تمرین را ترفیع دانستن","Falsch: „Ich bin jetzt Schichtleiter“, weil ein Übungsplan vereinbart ist. Richtig: Übung und tatsächliche Aufgabenübertragung unterscheiden.":"اشتباه: «حالا رهبر نوبت هستم»، چون یک برنامهٔ تمرین توافق شده است. درست: تمرین و سپردن واقعی کار را جدا کنید.","Echte Personaldaten ungeprüft kopieren":"کاپی بی‌بررسی داده‌های واقعی کارکنان","Falsch: Reale Dienstpläne als private Kursdatei hochladen. Richtig: Freigegebene Beispieldaten verwenden.":"اشتباه: برنامه‌های کار واقعی را به عنوان فایل خصوصی کورس بارگذاری کنید. درست: داده‌های نمونهٔ اجازه‌داده‌شده را به کار ببرید.","Was ist konkret vereinbart?":"مشخصاً چه چیزی توافق شده است؟","Eine bereits übertragene Verantwortung für die Schichtplanung.":"مسئولیت از قبل سپرده‌شدهٔ برنامه‌ریزی نوبت‌ها.","Eine Besprechung des Übungsplans nächsten Dienstag.":"صحبت دربارهٔ برنامهٔ تمرین سه‌شنبهٔ آینده.","Eine verbindliche Änderung der Vergütung nach der Übung.":"تغییر قطعی مزد بعد از تمرین.","Die Leitung sagt eine Übung und ihre Besprechung zu, keine Beförderung.":"رهبری یک تمرین و صحبت دربارهٔ آن را وعده می‌دهد، نه ترفیع.","Welche Daten passen zur Kursübung?":"کدام داده‌ها با تمرین کورس جورند؟","Freigegebene Beispieldaten.":"داده‌های نمونهٔ اجازه‌داده‌شده.","Eine private Kopie des aktuellen realen Dienstplans.":"یک کاپی خصوصی از برنامهٔ کار واقعی فعلی.","Echte Personaldaten aus einem früheren Betrieb.":"داده‌های واقعی کارکنان از یک شرکت قبلی.","Die Übung benötigt keine fremden vertraulichen Daten.":"این تمرین هیچ دادهٔ محرمانهٔ دیگران را لازم ندارد.","Welche Frage klärt den Lernbedarf?":"کدام سوال نیاز یادگیری را روشن می‌کند؟","Welcher Titel ergibt sich schon aus meinem Interesse?":"از علاقهٔ من از همین حالا کدام عنوان نتیجه می‌شود؟","Kann ich aus der Übung bereits eine feste Aufgabenübertragung ableiten?":"آیا می‌توانم از تمرین از همین حالا یک سپردن قطعی کار نتیجه بگیرم؟","Welche Tätigkeiten und Dokumentationen gehören zur Aufgabe?":"کدام کارها و ثبت‌ها جزو این کار هستند؟","Konkrete Anforderungen ermöglichen eine überprüfbare Entwicklung.":"خواسته‌های مشخص یک پیشرفت قابل بررسی را ممکن می‌کنند.","Trenne Gesprächswunsch, vereinbarten Lernversuch und tatsächliche Übertragung einer neuen Aufgabe.":"آرزوی گفتگو، آزمایش یادگیری توافق‌شده و سپردن واقعی یک کار تازه را جدا کنید.","Eine neue Aufgabe ansprechen":"مطرح کردن یک کار تازه","Rico: „Ich möchte künftig bei der Schichtplanung mitarbeiten. Welche Kenntnisse brauche ich?“ Leitung: „Sie müssten Dienstzeiten im System erfassen und Änderungen nachvollziehbar dokumentieren.“ Rico: „Könnte ich zuerst an einem Beispielplan üben?“ Leitung: „Ja, wir besprechen nächsten Dienstag einen freigegebenen Übungsplan.“":"ریکو: «می‌خواهم در آینده در برنامه‌ریزی نوبت‌ها همکاری کنم. کدام دانش را لازم دارم؟» رهبری: «باید ساعت‌های کار را در سیستم ثبت کنید و تغییرها را قابل پیگیری ثبت کنید.» ریکو: «می‌توانم اول با یک برنامهٔ نمونه تمرین کنم؟» رهبری: «بله، سه‌شنبهٔ آینده دربارهٔ یک برنامهٔ تمرین اجازه‌داده‌شده صحبت می‌کنیم.»","Anforderungen statt Titel klären":"روشن کردن خواسته‌ها به جای عنوان","Frage, welche konkreten Tätigkeiten zur neuen Aufgabe gehören und wie deren Qualität beurteilt wird. Ein attraktiver Titel erklärt noch keine Verantwortung. Ein erster Übungsversuch kann zeigen, welcher Lernbedarf tatsächlich besteht. Halte fest, welche Daten verwendet werden dürfen. Reale Dienstpläne enthalten persönliche Informationen und gehören nicht ungeprüft in eine private Lernkopie.":"بپرسید کدام کارهای مشخص جزو کار تازه هستند و کیفیت آن‌ها چطور ارزیابی می‌شود. یک عنوان جذاب هنوز هیچ مسئولیتی را توضیح نمی‌دهد. یک آزمایش تمرینی اول می‌تواند نشان دهد که واقعاً کدام نیاز یادگیری وجود دارد. ثبت کنید که کدام داده‌ها اجازهٔ استفاده دارند. برنامه‌های کار واقعی معلومات شخصی دارند و بدون بررسی در یک کاپی خصوصی یادگیری جا ندارند.","Vereinbarungen präzise benennen":"نام بردن دقیق توافق‌ها","Ein Übungsplan dient zum Lernen. Er überträgt dir noch nicht die Verantwortung für echte Schichten. Auch eine höhere Bezahlung folgt daraus nicht automatisch. Kläre neue Aufgaben und Bedingungen gesondert. Besprecht zuerst den Versuch: Was gelingt schon? Was musst du noch lernen? Haltet den nächsten Schritt gemeinsam fest.":"یک برنامهٔ تمرین برای یادگیری است. هنوز مسئولیت نوبت‌های واقعی را به شما نمی‌سپارد. یک پرداخت بیشتر هم خودکار از آن نتیجه نمی‌شود. کارها و شرط‌های تازه را جداگانه روشن کنید. اول دربارهٔ آزمایش صحبت کنید: چه چیزی از قبل موفق است؟ چه چیزی را هنوز باید یاد بگیرید؟ قدم بعدی را با هم ثبت کنید.","Den Lernversuch nachbereiten":"مرور آزمایش یادگیری","Notiere Ziel, freigegebenes Material, Termin und Rückmeldungsfrage. Nach der Besprechung hältst du fest, was gelingt und welcher nächste Schritt vereinbart ist. Verwende keine vertraulichen Personaldaten in einem Kursfeld. Eine sachliche Nachfrage wie „Welche Dokumentation fehlt noch?“ führt weiter als die Erwartung, ein Übungsplan müsse automatisch eine neue Stelle auslösen.":"هدف، مواد اجازه‌داده‌شده، وقت و سوال بازخورد را یادداشت کنید. بعد از صحبت ثبت می‌کنید که چه چیزی موفق است و کدام قدم بعدی توافق شده است. هیچ دادهٔ محرمانهٔ کارکنان را در یک خانهٔ کورس به کار نبرید. یک سوال واقع‌بینانه مثل „Welche Dokumentation fehlt noch?“ (کدام ثبت هنوز کم است؟) بیشتر پیش می‌برد تا این انتظار که یک برنامهٔ تمرین باید خودکار یک کار تازه بیاورد.","Den Lernversuch ergänzen":"کامل کردن آزمایش یادگیری","Setze „Dienstag“ und „Übungsplan“ ein.":"„Dienstag“ (سه‌شنبه) و „Übungsplan“ (برنامهٔ تمرین) را بگذارید.","Übernimm Termin und Material aus der Vereinbarung.":"وقت و مواد را از توافق بگیرید.","Die Angaben beschreiben die tatsächlich zugesagte Übung.":"این معلومات تمرین واقعاً وعده‌شده را توصیف می‌کنند.","Die Besprechung ist nächsten ___.":"Die Besprechung ist nächsten ___. (صحبت ___ آینده است.)","Rico erstellt einen freigegebenen ___.":"Rico erstellt einen freigegebenen ___. (ریکو یک ___ اجازه‌داده‌شده می‌سازد.)","Entwicklungsstände unterscheiden":"جدا کردن مرحله‌های پیشرفت","Ordne die Aussagen zu.":"گفته‌ها را وصل کنید.","Nicht jede Aussage hat dieselbe Verbindlichkeit oder Reichweite.":"هر گفته همان اندازه قطعیت یا دامنه را ندارد.","Die Zuordnung macht den tatsächlichen Entwicklungsstand sichtbar.":"این وصل کردن مرحلهٔ واقعی پیشرفت را قابل دید می‌کند.","Ich möchte mitarbeiten.":"می‌خواهم همکاری کنم.","Wir besprechen einen Übungsplan.":"دربارهٔ یک برنامهٔ تمرین صحبت می‌کنیم.","Neue Bedingungen gesondert klären":"شرط‌های تازه را جداگانه روشن کردن","Den Besprechungstag hören":"شنیدن روز صحبت","An welchem Tag wird der Übungsplan besprochen?":"در کدام روز دربارهٔ برنامهٔ تمرین صحبت می‌شود؟","Gesucht ist der ausdrücklich vereinbarte Tag.":"روز صریحاً توافق‌شده پرسیده شده است.","Die Rückmeldung zum Plan ist für Dienstag vorgesehen.":"بازخورد دربارهٔ برنامه برای سه‌شنبه (Dienstag) پیش‌بینی شده است.","Ein Entwicklungsgespräch festhalten":"ثبت یک گفتگوی پیشرفت","Schreibe vier Sätze zu Wunsch, Anforderungen, Übung und begrenzter Reichweite.":"چهار جمله دربارهٔ آرزو، خواسته‌ها، تمرین و دامنهٔ محدود بنویسید.","Halte die tatsächliche Vereinbarung statt gewünschter Folgen fest.":"توافق واقعی را ثبت کنید، نه نتیجه‌های دلخواه را.","Die Notiz macht Lernziel und Reichweite des Gesprächs überprüfbar.":"این یادداشت هدف یادگیری و دامنهٔ گفتگو را قابل بررسی می‌کند.","Ist der Entwicklungswunsch konkret?":"آیا آرزوی پیشرفت مشخص است؟","Nennst du beide Tätigkeitsanforderungen?":"آیا هر دو خواستهٔ کار را نام می‌برید؟","Sind Termin und freigegebenes Übungsmaterial enthalten?":"آیا وقت و مواد تمرین اجازه‌داده‌شده در آن هست؟","Bleiben Übung und mögliche Vertragsänderung getrennt?":"آیا تمرین و تغییر احتمالی قرارداد جدا می‌مانند؟","Stand: November 2026. Allgemeine Information, keine Rechtsberatung. Prüfe aktuelle Regeln bei bmas.de.":"وضعیت: نوامبر 2026. معلومات عمومی، نه مشورهٔ حقوقی. قاعده‌های فعلی را در bmas.de بررسی کنید.","BMAS: Arbeitsbedingungen und Weiterbildung":"BMAS: شرط‌های کار و آموزش بیشتر","Ein Lernversuch ist keine automatische Änderung der Arbeitsbedingungen.":"یک آزمایش یادگیری تغییر خودکار شرط‌های کار نیست.","Für eine Übung werden geeignete und freigegebene Daten verwendet.":"برای یک تمرین داده‌های مناسب و اجازه‌داده‌شده به کار می‌روند.","Weiterbildung und Beratung":"آموزش بیشتر و مشوره","Eine Gründungsidee mit einem einfachen Plan prüfen":"بررسی یک ایدهٔ کسب‌وکار با یک برنامهٔ ساده","Du beschreibst Kundennutzen, Kosten und Zahlungszeitpunkte, bevor du Geld bindest.":"شما فایدهٔ مشتری، هزینه‌ها و وقت‌های پرداخت را توصیف می‌کنید، پیش از اینکه پول را درگیر کنید.","Zustimmung als Nachfragebeweis lesen":"موافقت را مدرک تقاضا خواندن","Falsch: Aus Lob von Freunden sichere bezahlte Aufträge ableiten. Richtig: Tatsächlichen Bedarf und Zahlungsbereitschaft prüfen.":"اشتباه: از تعریف دوستان سفارش‌های پولی مطمئن نتیجه بگیرید. درست: نیاز واقعی و آمادگی پرداخت را بررسی کنید.","Späteren Eingang als sofort verfügbares Geld rechnen":"دریافت بعدی را پول فوراً در دسترس حساب کردن","Falsch: Ende des Monats erwartetes Geld schon vor Eingang als verfügbar ausgeben. Richtig: Ein- und Auszahlungen nach Zeitpunkt planen.":"اشتباه: پولی را که آخر ماه انتظار می‌رود پیش از رسیدن در دسترس خرج کنید. درست: دریافت‌ها و پرداخت‌ها را بر اساس وقت برنامه‌ریزی کنید.","Wie viel bleibt nach der sofortigen Ausgabe im Beispiel?":"در مثال بعد از خرج فوری چقدر می‌ماند؟","350 Euro bereits vor dem späteren Eingang.":"350 یورو از قبل پیش از دریافت بعدی.","550 Euro nach bloßer Addition beider Einnahmen.":"550 یورو بعد از جمع سادهٔ هر دو درآمد.","100 Euro.":"100 یورو.","Von 300 Euro werden zuerst 200 Euro ausgegeben; der spätere Eingang zählt noch nicht.":"از 300 یورو اول 200 یورو خرج می‌شود؛ دریافت بعدی هنوز حساب نمی‌شود.","Was ist durch freundliches Lob noch nicht belegt?":"با تعریف دوستانه هنوز چه چیزی ثابت نشده است؟","Eine freundliche persönliche Reaktion auf die Idee.":"یک واکنش شخصی دوستانه به ایده.","Tatsächliche bezahlte Nachfrage.":"تقاضای واقعی پولی.","Dass die Idee bereits anderen Personen vorgestellt wurde.":"اینکه ایده از قبل به اشخاص دیگر معرفی شده است.","Zahlungsbereitschaft und konkrete Aufträge müssen gesondert geprüft werden.":"آمادگی پرداخت و سفارش‌های مشخص باید جداگانه بررسی شوند.","Was unterscheidet Liquiditätsplanung besonders?":"چه چیزی برنامه‌ریزی نقدینگی را به‌خصوص متمایز می‌کند؟","Die Zeitpunkte tatsächlicher Ein- und Auszahlungen.":"وقت‌های دریافت‌ها و پرداخت‌های واقعی.","Nur die erwartete Gesamtsumme aller späteren Umsätze.":"فقط مجموع مورد انتظار همهٔ فروش‌های بعدی.","Nur die monatlichen Erträge ohne Zahlungstermine.":"فقط درآمدهای ماهانه بدون تاریخ‌های پرداخت.","Fällige Zahlungen benötigen zu diesem Zeitpunkt verfügbare Mittel.":"پرداخت‌های سررسید در همان وقت پول در دسترس لازم دارند.","Prüfe zuerst mit einer kleinen Recherche, ob Menschen das konkrete Angebot brauchen und zu welchen Bedingungen.":"اول با یک تحقیق کوچک بررسی کنید که آیا مردم پیشنهاد مشخص را لازم دارند و با کدام شرط‌ها.","Eine Geschäftsidee hinterfragen":"زیر سوال بردن یک ایدهٔ کسب‌وکار","Amal: „Ich möchte einen Fahrradservice anbieten. Viele finden die Idee gut.“ Berater: „Wer würde tatsächlich bezahlen?“ Amal: „Das muss ich noch prüfen.“ Berater: „Welche Kosten fallen an, bevor Geld eingeht?“ Amal: „Werkzeug und Raum. Ich brauche einen Plan statt nur Zustimmung von Freunden.“":"امل: «می‌خواهم خدمات بایسکل ارائه دهم. بسیاری ایده را خوب می‌دانند.» مشاور: «چه کسی واقعاً پول می‌دهد؟» امل: «این را هنوز باید بررسی کنم.» مشاور: «پیش از اینکه پول بیاید کدام هزینه‌ها پیش می‌آیند؟» امل: «ابزار و جا. من یک برنامه لازم دارم، نه فقط موافقت دوستان.»","Kundennutzen und Annahmen beschreiben":"توصیف فایدهٔ مشتری و فرض‌ها","Ein Businessplan verbindet Angebot, Zielgruppe, Umsetzung und finanzielle Planung. Eine freundliche Reaktion ist noch kein bezahlter Auftrag. Notiere, welches Problem du lösen willst und welche Annahmen du testen musst. Ein kleines Gespräch mit möglichen Kunden kann Hinweise liefern, aber keine sichere Nachfrage beweisen. Bezeichne Schätzungen klar als Schätzungen.":"یک Businessplan (برنامهٔ کسب‌وکار) پیشنهاد، گروه هدف، اجرا و برنامه‌ریزی مالی را وصل می‌کند. یک واکنش دوستانه هنوز یک سفارش پولی نیست. یادداشت کنید کدام مشکل را می‌خواهید حل کنید و کدام فرض‌ها را باید آزمایش کنید. یک گفتگوی کوچک با مشتریان احتمالی می‌تواند نشانه بدهد، اما تقاضای مطمئن را ثابت نمی‌کند. تخمین‌ها را روشن تخمین بنامید.","Ertrag und Zahlungsfähigkeit unterscheiden":"جدا کردن درآمد و توانایی پرداخت","Umsatz ist das Geld aus deinen Verkäufen, bevor du Kosten abziehst. Liquidität heißt: Du kannst fällige Rechnungen rechtzeitig bezahlen. Im Beispiel hast du zuerst 300 Euro. Davon zahlst du sofort 200 Euro. Bis zum späteren Eingang von 250 Euro bleiben 100 Euro. Plane deshalb nicht nur Beträge, sondern auch Zahlungstage.":"Umsatz (فروش) پول از فروش‌های شماست، پیش از اینکه هزینه‌ها را کم کنید. Liquidität (نقدینگی) یعنی: می‌توانید صورت‌حساب‌های سررسید را به‌موقع بپردازید. در مثال اول 300 یورو دارید. از آن فوراً 200 یورو می‌پردازید. تا دریافت بعدی 250 یورو، 100 یورو می‌ماند. به همین دلیل نه فقط مبلغ‌ها، بلکه روزهای پرداخت را هم برنامه‌ریزی کنید.","Vor Verpflichtungen Beratung nutzen":"استفاده از مشوره پیش از تعهدها","Prüfe nötige berufliche, gewerbliche, steuerliche und gegebenenfalls aufenthaltsrechtliche Voraussetzungen mit den zuständigen Stellen. Die Einordnung hängt vom konkreten Vorhaben ab. Die KfW und das Existenzgründungsportal bieten Orientierung zur Geschäfts- und Finanzplanung. Ein Informationsangebot ist keine Finanzierung oder Erlaubnis. Unterschreibe keinen kostenpflichtigen Vertrag allein aufgrund dieser Kursidee.":"پیش‌شرط‌های لازم مسلکی، تجاری، مالیاتی و در صورت لزوم اقامتی را با بخش‌های مسئول بررسی کنید. جا دادن آن به طرح مشخص بستگی دارد. KfW و پورتال Existenzgründungsportal راهنمایی دربارهٔ برنامه‌ریزی کسب‌وکار و مالی می‌دهند. یک پیشنهاد معلوماتی تأمین مالی یا اجازه نیست. فقط به خاطر این ایدهٔ کورس هیچ قرارداد پولی امضا نکنید.","Den Kassenstand berechnen":"حساب کردن موجودی صندوق","Setze die Beträge ohne Währung ein.":"مبلغ‌ها را بدون واحد پول بگذارید.","Beachte zuerst die Reihenfolge und dann die Addition.":"اول به ترتیب و بعد به جمع توجه کنید.","Vor dem Eingang sind 100, danach im vereinfachten Beispiel 350 Euro verfügbar.":"پیش از دریافت 100 و بعد از آن در مثال ساده‌شده 350 یورو در دسترس است.","300 minus 200 ergibt ___.":"300 منهای 200 می‌شود ___.","Nach späterem Eingang von 250 sind es dann ___.":"بعد از دریافت بعدی 250، می‌شود ___.","Planbegriffe zuordnen":"وصل کردن مفهوم‌های برنامه","Verbinde die Frage mit dem Bereich.":"سوال را به بخش وصل کنید.","Inhalt, Aufwand und Zahlungszeitpunkt sind verschiedene Prüfungen.":"محتوا، زحمت و وقت پرداخت بررسی‌های مختلف‌اند.","Ein tragfähiger Plan braucht mehr als ein positives Gefühl.":"یک برنامهٔ پایدار بیشتر از یک احساس مثبت لازم دارد.","Wer bezahlt wofür?":"چه کسی برای چه چیزی پول می‌دهد؟","Was wird angeschafft?":"چه چیزی خریده می‌شود؟","Wann ist Geld verfügbar?":"پول چه وقت در دسترس است؟","Die erste Ausgabe verstehen":"فهمیدن اولین خرج","Wofür braucht Amal zuerst Geld? Nenne das erste genannte Beispiel.":"امل اول برای چه چیزی پول لازم دارد؟ اولین مثال نام‌برده را بگویید.","Gesucht ist die zuerst genannte Anschaffung.":"اولین خرید نام‌برده پرسیده شده است.","Werkzeug gehört zu den Kosten vor ersten möglichen Einnahmen.":"ابزار (Werkzeug) جزو هزینه‌های پیش از اولین درآمدهای احتمالی است.","Eine Gründungsprüfung skizzieren":"طرح یک بررسی کسب‌وکار","Schreibe vier Sätze zu Angebot, offener Nachfrage, anfänglichen Kosten und Beratung.":"چهار جمله دربارهٔ پیشنهاد، تقاضای باز، هزینه‌های اولیه و مشوره بنویسید.","Eine Skizze soll offene Prüfungen sichtbar machen, keinen Erfolg garantieren.":"یک طرح باید بررسی‌های باز را قابل دید کند، نه اینکه موفقیت را تضمین کند.","Der Plan verbindet Kundennutzen, zeitliche Geldplanung und fachkundige Klärung.":"این برنامه فایدهٔ مشتری، برنامه‌ریزی زمانی پول و روشن‌سازی متخصص را وصل می‌کند.","Ist das Angebot verständlich beschrieben?":"آیا پیشنهاد قابل فهم توصیف شده است؟","Bleibt die Nachfrage als zu prüfende Annahme erkennbar?":"آیا تقاضا یک فرض قابل بررسی شناخته می‌ماند؟","Berücksichtigst du Kosten vor ersten Einnahmen?":"آیا هزینه‌های پیش از اولین درآمدها را در نظر می‌گیرید؟","Planst du Beratung vor verbindlichen Verträgen?":"آیا پیش از قراردادهای قطعی مشوره را برنامه‌ریزی می‌کنید؟","Stand: November 2026. Allgemeine Information, keine Rechtsberatung. Prüfe aktuelle Regeln bei make-it-in-germany.com.":"وضعیت: نوامبر 2026. معلومات عمومی، نه مشورهٔ حقوقی. قاعده‌های فعلی را در make-it-in-germany.com بررسی کنید.","Make it in Germany: Gründung vorbereiten":"Make it in Germany: آماده کردن تأسیس کسب‌وکار","Eine Geschäftsidee enthält Annahmen, die vor einer großen Bindung geprüft werden.":"یک ایدهٔ کسب‌وکار فرض‌هایی دارد که پیش از یک تعهد بزرگ بررسی می‌شوند.","Liquiditätsplanung beachtet, wann Geld tatsächlich verfügbar ist.":"برنامه‌ریزی نقدینگی توجه می‌کند که پول واقعاً چه وقت در دسترس است.","Gründungsplanung und Finanzierung":"برنامه‌ریزی تأسیس و تأمین مالی","Einen überprüfbaren Entwicklungsplan erstellen":"ساختن یک برنامهٔ پیشرفت قابل بررسی","Du bündelst Ziel, offene Voraussetzungen und nächste Schritte mit einer regelmäßigen Rückschau.":"شما هدف، پیش‌شرط‌های باز و قدم‌های بعدی را با یک مرور منظم جمع می‌کنید.","Alle Möglichkeiten als zugesagt eintragen":"همهٔ امکان‌ها را وعده‌شده نوشتن","Falsch: Anerkennung, Förderung und Gründung ohne Entscheidung als erledigt markieren. Richtig: Den tatsächlichen Stand jedes Verfahrens getrennt festhalten.":"اشتباه: به رسمیت شناختن، حمایت و تأسیس را بدون تصمیم انجام‌شده علامت بزنید. درست: وضعیت واقعی هر روند را جدا ثبت کنید.","Eigenen Termin als Behördenfrist ausgeben":"وقت خودتان را مهلت اداره جلوه دادن","Falsch: Aus dem eigenen Wochenziel eine sichere Bearbeitungszusage ableiten. Richtig: Eigene Handlung und fremde Entscheidung auseinanderhalten.":"اشتباه: از هدف هفتهٔ خود یک وعدهٔ مطمئن رسیدگی نتیجه بگیرید. درست: کار خودتان و تصمیم دیگران را جدا نگه دارید.","Was klärt Farah zuerst?":"فرح اول چه چیزی را روشن می‌کند؟","Die zuständige Anerkennungsstelle.":"بخش مسئول به رسمیت شناختن.","Direkt die Anmeldung für einen noch ungeprüften Kurs.":"مستقیم ثبت‌نام برای یک کورس هنوز بررسی‌نشده.","Zuerst einen Gründungsvertrag ohne weitere Recherche.":"اول یک قرارداد تأسیس بدون تحقیق بیشتر.","Die Zuständigkeitsklärung ist im Gespräch ausdrücklich der erste Schritt.":"روشن کردن مسئولیت در گفتگو صریحاً قدم اول است.","Welcher Meilenstein ist überprüfbar?":"کدام نقطهٔ عطف قابل بررسی است؟","Eine sichere Behördenentscheidung bis zum eigenen Wunschtermin.":"یک تصمیم مطمئن اداره تا وقت دلخواه خودتان.","Nächste Woche die zuständige Stelle kontaktieren und die Antwort dokumentieren.":"هفتهٔ آینده با بخش مسئول تماس گرفتن و جواب را ثبت کردن.","Eine Kursanmeldung trotz ungeklärter Voraussetzungen.":"یک ثبت‌نام کورس با وجود پیش‌شرط‌های روشن‌نشده.","Die eigene Kontaktaufnahme und Dokumentation sind konkrete Handlungen.":"تماس گرفتن و ثبت خودتان کارهای مشخص‌اند.","Wann wird ein Status auf erledigt gesetzt?":"یک وضعیت چه وقت «انجام‌شده» گذاشته می‌شود؟","Sobald der Antrag abgeschickt wurde, unabhängig von der Entscheidung.":"همین که درخواست فرستاده شد، بدون توجه به تصمیم.","Sobald die Möglichkeit in einer Beratung angesprochen wurde.":"همین که امکان در یک مشوره مطرح شد.","Nach der tatsächlich abgeschlossenen Handlung oder bestätigten Entscheidung.":"بعد از کار واقعاً تمام‌شده یا تصمیم تأییدشده.","Ein Status muss durch ein eingetretenes Ereignis gedeckt sein.":"یک وضعیت باید با یک رویداد واقعی پوشیده شود.","Plane für die nächste Woche eine konkrete Klärung und für den folgenden Monat ein überprüfbares Ergebnis.":"برای هفتهٔ آینده یک روشن‌سازی مشخص و برای ماه بعد یک نتیجهٔ قابل بررسی برنامه‌ریزی کنید.","Drei mögliche Wege ordnen":"مرتب کردن سه راه ممکن","Farah: „Ich denke an Anerkennung, Weiterbildung und später vielleicht Selbstständigkeit.“ Berater: „Was hat jetzt Vorrang?“ Farah: „Zuerst kläre ich die zuständige Anerkennungsstelle. Danach vergleiche ich zwei passende Kurse. Über Gründung entscheide ich erst nach einer eigenen Recherche.“ Berater: „Dann hat jeder Schritt einen klaren Zweck und eine spätere Prüfung.“":"فرح: «به به رسمیت شناختن، آموزش بیشتر و بعداً شاید کار آزاد فکر می‌کنم.» مشاور: «حالا چه چیزی اولویت دارد؟» فرح: «اول بخش مسئول به رسمیت شناختن را روشن می‌کنم. بعد دو کورس مناسب را مقایسه می‌کنم. دربارهٔ تأسیس فقط بعد از یک تحقیق خودم تصمیم می‌گیرم.» مشاور: «پس هر قدم یک هدف روشن و یک بررسی بعدی دارد.»","Abhängigkeiten sichtbar machen":"قابل دید کردن وابستگی‌ها","Ein Entwicklungsplan muss nicht alle Möglichkeiten gleichzeitig verfolgen. Markiere, welche Entscheidung eine andere voraussetzt. Wähle einen Kurs passend zu dem, was du noch lernen musst. Kläre vor der Anmeldung, wie du ihn finanzierst. Ein offener Antrag ist noch keine Zusage. Halte daher für jeden Schritt Ausgangslage, benötigte Information und nächste Handlung fest.":"یک برنامهٔ پیشرفت لازم نیست همهٔ امکان‌ها را هم‌زمان دنبال کند. علامت بزنید کدام تصمیم تصمیم دیگری را پیش‌شرط دارد. کورسی را انتخاب کنید که با آنچه هنوز باید یاد بگیرید جور باشد. پیش از ثبت‌نام روشن کنید که آن را چطور تأمین مالی می‌کنید. یک درخواست باز هنوز وعده نیست. پس برای هر قدم وضعیت شروع، معلومات لازم و کار بعدی را ثبت کنید.","Termine und Ergebnisse verbinden":"وصل کردن وقت‌ها و نتیجه‌ها","Ein Meilenstein ist ein prüfbares Zwischenergebnis. Notiere zum Beispiel: „Nächste Woche frage ich nach der zuständigen Stelle.“ Das ist dein eigener Arbeitsschritt. Du kannst damit keine Antwort der Behörde bis zu diesem Termin garantieren. Plane Wartezeit ein. Markiere, auf welche Antwort du vor einer weiteren Entscheidung noch angewiesen bist.":"یک Meilenstein (نقطهٔ عطف) یک نتیجهٔ میانی قابل بررسی است. مثلاً یادداشت کنید: „Nächste Woche frage ich nach der zuständigen Stelle.“ (هفتهٔ آینده دربارهٔ بخش مسئول می‌پرسم.) این قدم کاری خودتان است. با آن نمی‌توانید جواب اداره را تا آن وقت تضمین کنید. وقت انتظار را برنامه‌ریزی کنید. علامت بزنید پیش از یک تصمیم دیگر هنوز به کدام جواب نیاز دارید.","Den Plan nach Belegen aktualisieren":"تازه کردن برنامه بر اساس مدرک‌ها","Prüfe regelmäßig, welche Antwort tatsächlich eingegangen und welche Aufgabe erledigt ist. Passe die Reihenfolge an, wenn neue Informationen vorliegen. Eine verworfene Kursidee kann ein sinnvolles Ergebnis sorgfältiger Prüfung sein. Nach dem Kurs hast du einen Plan für deine nächsten Schritte. Über Anerkennung, Finanzierung oder eine nötige Erlaubnis entscheiden die zuständigen Stellen.":"منظم بررسی کنید کدام جواب واقعاً رسیده و کدام کار انجام شده است. اگر معلومات تازه آمد، ترتیب را تطبیق دهید. یک ایدهٔ کورس کنارگذاشته‌شده می‌تواند نتیجهٔ معقول یک بررسی دقیق باشد. بعد از کورس یک برنامه برای قدم‌های بعدی خود دارید. دربارهٔ به رسمیت شناختن، تأمین مالی یا یک اجازهٔ لازم بخش‌های مسئول تصمیم می‌گیرند.","Die Reihenfolge ergänzen":"کامل کردن ترتیب","Setze „Zuständigkeit“ und „Kurse“ ein.":"„Zuständigkeit“ (مسئولیت) و „Kurse“ (کورس‌ها) را بگذارید.","Die Reihenfolge folgt den noch offenen Voraussetzungen.":"ترتیب از پیش‌شرط‌های هنوز باز پیروی می‌کند.","Farah geht schrittweise vor, statt alles als erledigt zu behandeln.":"فرح قدم به قدم پیش می‌رود، به جای اینکه همه چیز را انجام‌شده حساب کند.","Zuerst klärt Farah die ___.":"Zuerst klärt Farah die ___. (اول فرح ___ را روشن می‌کند.)","Danach vergleicht sie zwei passende ___.":"Danach vergleicht sie zwei passende ___. (بعد دو ___ مناسب را مقایسه می‌کند.)","Planstände unterscheiden":"جدا کردن وضعیت‌های برنامه","Verbinde die Angabe mit dem Status.":"معلومات را به وضعیت وصل کنید.","Eine versandte Anfrage ist noch kein Bescheid.":"یک درخواست فرستاده‌شده هنوز تصمیم‌نامه نیست.","Die Zuordnung hält Handlung und Antwort auseinander.":"این وصل کردن کار و جواب را جدا نگه می‌دارد.","Stelle noch unklar":"بخش هنوز نامشخص","Anfrage verschickt":"درخواست فرستاده شد","Bescheid erhalten":"تصمیم‌نامه رسید","Den ersten Weg hören":"شنیدن راه اول","Welches Verfahren möchte Farah zuerst klären? Antworte mit einem Nomen.":"فرح اول می‌خواهد کدام روند را روشن کند؟ با یک اسم (به آلمانی) جواب دهید.","Gesucht ist der priorisierte erste Weg.":"راه اول دارای اولویت پرسیده شده است.","Farah beginnt mit der Anerkennungsfrage.":"فرح با سوال به رسمیت شناختن (Anerkennung) شروع می‌کند.","Einen nächsten Entwicklungsplan schreiben":"نوشتن یک برنامهٔ پیشرفت بعدی","Schreibe vier Sätze mit erster Klärung, anschließendem Vergleich, offener Finanzierung und Rückschau.":"چهار جمله با اولین روشن‌سازی، مقایسهٔ بعدی، تأمین مالی باز و مرور بنویسید.","Setze Termine für eigene Handlungen und markiere fremde Entscheidungen als offen.":"برای کارهای خودتان وقت بگذارید و تصمیم‌های دیگران را باز علامت بزنید.","Der Plan schafft konkrete Weiterarbeit ohne Anerkennung oder Förderung vorwegzunehmen.":"این برنامه کار مشخص بعدی می‌سازد، بدون اینکه به رسمیت شناختن یا حمایت را پیشاپیش فرض کند.","Ist die erste Handlung konkret und zeitlich eingegrenzt?":"آیا اولین کار مشخص و از نظر وقت محدود است؟","Baut der Kursvergleich auf Anforderungen auf?":"آیا مقایسهٔ کورس بر خواسته‌ها ساخته شده است؟","Bleibt die Finanzierung bis zur Klärung offen?":"آیا تأمین مالی تا روشن شدن باز می‌ماند؟","Planst du eine Rückschau anhand tatsächlicher Belege?":"آیا یک مرور بر اساس مدرک‌های واقعی برنامه‌ریزی می‌کنید؟","Bundesagentur für Arbeit: Anerkennungsweg":"ادارهٔ فدرال کار: راه به رسمیت شناختن","Ein Meilenstein beschreibt ein überprüfbares Zwischenergebnis.":"یک نقطهٔ عطف یک نتیجهٔ میانی قابل بررسی را توصیف می‌کند.","Der Plan wird nach tatsächlichen Antworten und nicht nach Wunschstatus aktualisiert.":"برنامه بر اساس جواب‌های واقعی تازه می‌شود، نه بر اساس وضعیت دلخواه.","Anerkennung: Verfahrensorientierung":"به رسمیت شناختن: راهنمایی روند"};})(typeof window!=="undefined"?window:globalThis);
